ing_not_primary;require_primary_source_link_before_chat_use", "blocking_flags": "", "human_decision_required": "yes", "initial_review_status": "pending_human_approval", "approval_decision": "pending", "reference_document_status_on_import": "in_review", "knowledge_document_status_on_import": "not_created_until_reference_approved", "is_chat_eligible": "false", "chat_priority": "n/a_until_approved", "supabase_dml_status": "not_applied", "origin": "legacy_source_file", "origin_file": "research_data/knowledge_base.json", "content_preview": "مجموع فتاوى شيخ الإسلام أحمد بن عبد الحليم بن تيمية (ت 728 هـ)، يحتوي على فتاوى متعلقة بالوقف من المذهب الحنبلي.\n\nاستبدال الوقف:\n- يجوز استبدال الوقف بخير منه إذا كان ذلك أنفع للموقوف عليهم\n- مثال: إذا وقف داراً أو حانوتاً أو بستاناً أو قرية يكون مغلها قليلاً، فيبدلها بما هو أكثر غلة\n\nالوقف على جهة مباحة:\n- الوقف على الأغنياء جائز\n- الوقف على المدارس والمساجد من أفضل الأوقاف\n\nشروط الواقف:\n- يجب العمل بشرط الواقف ما لم يخالف الشرع\n- إذا شرط الواقف ألا ينزل في المدرسة إلا من لم يكن له وظيفة، وجب العمل بشرطه", "batch": "knowledge_batch_05", "import_policy": "full_recovered_records_import", "db_record_kind": "review_import_record", "requested_operator_mode": "approved_and_chat_visible_pack_available", "legacy_registry_key": "f0b0449ddbca", "original_kb04_status": "pending_human_approval", "original_hold_or_triage_bucket": "P3_SUPPORTING_REFERENCE_REVIEW"}, "tags": ["jurisprudence", "fiqh", "P3_SUPPORTING_REFERENCE_REVIEW", "old_db_recovered", "kb05"]}]$kb05payload$::jsonb) as x(
    queue_no integer,
    registry_key text,
    title text,
    document_type text,
    language text,
    authority_level text,
    domain_scope text,
    source_type text,
    summary text,
    content_text text,
    category text,
    source_url text,
    author text,
    year text,
    review_bucket text,
    planned_import_stage text,
    metadata_json jsonb,
    tags jsonb
  )
),
reference_insert as (
  insert into assistant.reference_documents (
    source_id,
    title,
    document_type,
    language,
    status,
    authority_level,
    domain_scope,
    source_type,
    summary,
    content_text,
    content_hash,
    metadata_json,
    approval_version,
    review_notes,
    review_decision,
    reviewed_at
  )
  select
    (select id from source_row),
    p.title,
    p.document_type,
    p.language,
    case when (select approve_on_import from params) then 'approved' else 'in_review' end,
    p.authority_level,
    p.domain_scope,
    p.source_type,
    nullif(left(p.summary, 4000), ''),
    p.content_text,
    md5(coalesce(p.content_text,'') || '|' || p.registry_key),
    p.metadata_json || jsonb_build_object(
      'kb05_db_import_status','inserted_to_reference_documents',
      'kb05_safe_sql_mode','review_only_no_chat',
      'approved_on_import',(select approve_on_import from params),
      'chat_visible_on_import',(select chat_visible_on_import from params)
    ),
    1,
    'KB05 full old DB recovered import. Safe fallback imports all recovered records to DB as review-only references; no chat publication.',
    case when (select approve_on_import from params) then 'approve' else null end,
    case when (select approve_on_import from params) then now() else null end
  from payload p
  where not exists (
    select 1
    from assistant.reference_documents rd
    where rd.metadata_json->>'legacy_registry_key' = p.registry_key
       or rd.metadata_json->>'registry_key' = p.registry_key
  )
  returning id, title, content_text, summary, authority_level, domain_scope, source_type, metadata_json
),
reference_all as (
  select id, title, content_text, summary, authority_level, domain_scope, source_type, metadata_json
  from reference_insert
  union all
  select rd.id, rd.title, rd.content_text, rd.summary, rd.authority_level, rd.domain_scope, rd.source_type, rd.metadata_json
  from assistant.reference_documents rd
  join payload p on rd.metadata_json->>'legacy_registry_key' = p.registry_key
),
knowledge_insert as (
  insert into assistant.knowledge_documents (
    reference_document_id,
    source_id,
    title,
    category,
    status,
    authority_level,
    domain_scope,
    source_type,
    summary,
    content,
    tags,
    is_chat_eligible,
    chat_priority,
    grounding_weight,
    approval_version,
    review_notes,
    review_decision,
    reviewed_at,
    metadata_json
  )
  select
    r.id,
    (select id from source_row),
    r.title,
    coalesce(r.metadata_json->>'target_category', r.metadata_json->>'legacy_category', 'recovered'),
    case when (select approve_on_import from params) then 'approved' else 'in_review' end,
    r.authority_level,
    r.domain_scope,
    r.source_type,
    nullif(left(coalesce(r.summary,''), 4000), ''),
    coalesce(nullif(r.content_text,''), r.title),
    coalesce(r.metadata_json->'tags', '[]'::jsonb),
    (select chat_visible_on_import from params),
    (select default_chat_priority from params),
    1.000,
    1,
    'KB05 derived knowledge record created from recovered old DB reference import.',
    case when (select approve_on_import from params) then 'approve' else null end,
    case when (select approve_on_import from params) then now() else null end,
    r.metadata_json || jsonb_build_object(
      'kb05_db_import_status','inserted_to_knowledge_documents',
      'derived_from_reference_document_id', r.id,
      'approved_on_import',(select approve_on_import from params),
      'chat_visible_on_import',(select chat_visible_on_import from params),
      'operator_warning','Safe fallback mode: no knowledge document should be created because create_knowledge_documents=false.'
    )
  from reference_all r
  where (select create_knowledge_documents from params)
    and not exists (
      select 1
      from assistant.knowledge_documents kd
      where kd.metadata_json->>'legacy_registry_key' = r.metadata_json->>'legacy_registry_key'
    )
  returning id, reference_document_id
),
citation_insert as (
  insert into assistant.knowledge_citations (
    knowledge_document_id,
    reference_document_id,
    citation_type,
    locator,
    excerpt,
    metadata_json
  )
  select
    k.id,
    k.reference_document_id,
    'self_reference',
    'KB05 recovered old DB import',
    null,
    jsonb_build_object('batch','knowledge_batch_05','citation_policy','derived knowledge cites recovered reference document')
  from knowledge_insert k
  where exists (
    select 1 from information_schema.tables
    where table_schema='assistant' and table_name='knowledge_citations'
  )
  returning id
)
select
  (select count(*) from payload) as payload_records,
  (select count(*) from reference_insert) as newly_inserted_reference_documents,
  (select count(*) from knowledge_insert) as newly_inserted_knowledge_documents,
  (select count(*) from citation_insert) as newly_inserted_citations,
  (select chat_visible_on_import from params) as chat_visible_on_import,
  (select approve_on_import from params) as approved_on_import;

commit;

